-- lunex-script | protected at publish time, decrypted only at runtime
local function lx_bxor(a, b)
	local r, p = 0, 1
	for i = 1, 8 do
		local ba, bb = a % 2, b % 2
		if ba ~= bb then r = r + p end
		a = (a - ba) / 2
		b = (b - bb) / 2
		p = p * 2
	end
	return r
end
local function lx_run(payload, keyhex)
	local kb = {}
	for i = 1, #keyhex, 2 do
		kb[#kb + 1] = tonumber(keyhex:sub(i, i + 1), 16)
	end
	local alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local data, bits, value = {}, 0, 0
	for i = 1, #payload do
		local c = payload:sub(i, i)
		if c == "=" then break end
		local idx = alpha:find(c, 1, true)
		if idx then
			value = value * 64 + (idx - 1)
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				data[#data + 1] = math.floor(value / (2 ^ bits)) % 256
				value = value % (2 ^ bits)
			end
		end
	end
	for i = 1, #data - 1, 2 do
		data[i], data[i + 1] = data[i + 1], data[i]
	end
	local out = {}
	for i = 1, #data do
		out[i] = string.char(lx_bxor(data[i], kb[((i - 1) % #kb) + 1]))
	end
	return table.concat(out)
end
loadstring(lx_run("", "d067206a5f46c4223e6047bb2bef9796f605db92cf245367"))()
